// joinLines ends each line with a newline, keeping at most maxLines of them
// (0 = all).
func joinLines(lines []string, maxLines int) string {
	if maxLines > 0 && len(lines) > maxLines {
		lines = lines[:maxLines]
	}
	var b strings.Builder
	for _, l := range lines {
		b.WriteString(l + "\\n")
	}
	return b.String()
}
